import {checkedAnswer} from './solve-graph.js';
const $=id=>document.getElementById(id);let controller=null,preview=null;
function render(data){if(!Array.isArray(data.answers)||!data.answers.length||data.answers.length>8)throw Error('Некорректный список вопросов');$('answers').replaceChildren();for(const item of data.answers){const result=checkedAnswer(item),row=document.createElement('div');row.className='answer';const h=document.createElement('h2');h.textContent=`${item.question}: ${result.answer}`;const p=document.createElement('p');p.textContent=result.note+(result.verified?' — проверено алгоритмом по распознанным данным':' — не подтверждено');row.append(h,p);$('answers').append(row);}}
$('file').onchange=()=>{if(preview)URL.revokeObjectURL(preview);const f=$('file').files[0];$('image').hidden=!f;if(f){preview=URL.createObjectURL(f);$('image').src=preview;}};
$('recompute').onclick=()=>{try{render(JSON.parse($('recognition').value));$('status').textContent='Пересчитано локально, без API.';}catch(e){$('status').textContent=e.message;}};
$('cancel').onclick=()=>controller?.abort();
$('run').onclick=async()=>{
 const key=$('key').value.trim(),model=$('model').value.trim(),file=$('file').files[0];if(!key.startsWith('AIza')||!/^gemini-[a-z0-9.-]+$/.test(model)||!file||!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>10*1024*1024){$('status').textContent='Нужны ключ Gemini, допустимая модель и изображение до 10 МБ.';return;}
 controller=new AbortController();$('run').disabled=true;$('cancel').disabled=false;const timer=setTimeout(()=>controller.abort(),60000);const start=performance.now();$('status').textContent='Распознавание и рассуждения… Время зависит от модели и сети; 15 секунд не гарантируются.';
 try{const contract=await (await fetch('./ai-contract.json')).json();const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});const generation={responseMimeType:'application/json',responseJsonSchema:contract.schema,maxOutputTokens:6144};if(model.startsWith('gemini-2.5-flash'))generation.thinkingConfig={thinkingBudget:2048};const response=await fetch('https://generativelanguage.googleapis.com/v1beta/models/'+encodeURIComponent(model)+':generateContent',{method:'POST',signal:controller.signal,headers:{'Content-Type':'application/json','x-goog-api-key':key},body:JSON.stringify({systemInstruction:{parts:[{text:contract.prompt}]},contents:[{role:'user',parts:[{text:'Read and solve all complete visible questions.'},{inlineData:{mimeType:file.type,data}}]}],generationConfig:generation})});if(!response.ok)throw Error('API HTTP '+response.status);const result=await response.json();const text=(result.candidates?.[0]?.content?.parts||[]).filter(p=>!p.thought).map(p=>p.text||'').join(' ');const parsed=JSON.parse(text);$('recognition').value=JSON.stringify(parsed,null,2);render(parsed);$('status').textContent=`Готово за ${((performance.now()-start)/1000).toFixed(1)} с. Проверь распознанный граф перед использованием ответа.`;
 }catch(e){$('status').textContent=e.name==='AbortError'?'Запрос отменён или превышено время ожидания. Повторный запрос может расходовать квоту.':e.message;}finally{clearTimeout(timer);controller=null;$('run').disabled=false;$('cancel').disabled=true;}
};
